    /// <summary>
    /// 
    /// </summary>
    /// <param name = "_itemId"></param>
    /// <param name = "_inventDimId"></param>
    /// <param name = "_fromUnit"></param>
    /// <param name = "_toUnit"></param>
    /// <param name = "_salesQty"></param>
    /// <returns></returns>
    protected SalesQty calculateSubstituteQty(ItemId               _fromItemId,
                                              ItemId               _toItemId,
                                              InventDimId          _inventDimId,
                                              UnitOfMeasureSymbol  _fromUnit,
                                              UnitOfMeasureSymbol  _toUnit,
                                              SalesQty             _salesQty)
    {
        SalesQty ret;

        if (_fromUnit == _toUnit)
        {
            ret  = _salesQty;
        }
        else
        {
            if (EcoResProductUnitConverter::canBeConvertedGivenUnitSymbolsForReleasedProduct(_toItemId, _inventDimId, _fromUnit, _toUnit))
            {
                ret  = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(_toItemId, _inventDimId, _salesQty, _fromUnit, _toUnit);
            }
            else
            {
                if (EcoResProductUnitConverter::canBeConvertedGivenUnitSymbolsForReleasedProduct(_fromItemId, _inventDimId, _fromUnit, InventTableModule::find(_fromItemId, ModuleInventPurchSales::Invent).UnitId)
                &&  EcoResProductUnitConverter::canBeConvertedGivenUnitSymbolsForReleasedProduct(_toItemId, _inventDimId, InventTableModule::find(_toitemId, ModuleInventPurchSales::Invent).UnitId, _toUnit))
                {
                    ret  = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(_fromItemId, _inventDimId, _salesQty, _fromUnit, InventTableModule::find(_fromItemId, ModuleInventPurchSales::Invent).UnitId, NoYes::No, NoYes::No);
                    ret  = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(_toItemId, _inventDimId, ret, InventTableModule::find(_toitemId, ModuleInventPurchSales::Invent).UnitId, _toUnit, NoYes::No, NoYes::No);
                    
                    ret = this.roundValue(ret, salesItemSubstitute.Rounding, _toUnit);
                }
                else
                {
                    ret = _salesQty;
                }
            }
        }

        return ret;
    }

    /// <summary>
    /// Applies rounding to a real value.
    /// </summary>
    /// <param name="_value">
    /// A real value.
    /// </param>
    /// <param name="_rounding">
    /// A rounding type.
    /// </param>
    /// <returns>
    /// A rounded real value.
    /// </returns>
    protected real roundValue(
        real                             _value,
        METSalesItemSubstitutionRounding _rounding,
        UnitOfMeasureSymbol              _toUnit)
    {
        real    ret;
        int     sign    = 1;

        switch (_rounding)
        {
            case METSalesItemSubstitutionRounding::ToNearest   :
                ret = decRound(sign * _value, this.roundingDecimalPrecision(_toUnit));
                break;

            case METSalesItemSubstitutionRounding::Up        :
                ret = roundUpDec(sign * _value, this.roundingDecimalPrecision(_toUnit));
                break;

            case METSalesItemSubstitutionRounding::Down      :
                ret = roundDownDec(sign * _value, this.roundingDecimalPrecision(_toUnit));
                break;
        }

        return sign * ret;
    }

    /// <summary>
    ///    Retrieves the decimal precision for the unit of measure to which to convert.
    /// </summary>
    /// <returns>
    ///    The decimal precision.
    /// </returns>
    protected UnitOfMeasureDecimalPrecision roundingDecimalPrecision(UnitOfMeasureSymbol _toUnit)
    {
        return UnitOfMeasure::findBySymbol(_toUnit).DecimalPrecision;;
    }

